    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        sortedDataTest,
        .{ &tree_data, &expected },
    );
}

test "can sort data-can sort if second number is greater than first" {
    const tree_data = [_]i32{ 2, 3 };
    const expected = [_]i32{ 2, 3 };
    try std.testing.checkAllAllocationFailures(
        std.testing.allocator,
        sortedDataTest,
        .{ &tree_data, &expected },
    );
